{
  "crossfield": 1,
  "name": "jaffle",
  "id": "org.queryfarm.examples.jaffle",
  "imports": [
    {
      "path": "jaffle-v1.ossie.json"
    }
  ],
  "policy": {
    "policy_version": 1,
    "metrics": [
      "order_count",
      "subtotal",
      "tax",
      "order_total",
      "item_count",
      "customer_count",
      "first_orders",
      "repeat_orders",
      "average_order_value",
      "revenue"
    ],
    "dimensions": [
      "orders.order_day",
      "orders.order_month",
      "orders.is_first",
      "products.name",
      "products.category",
      "stores.id",
      "stores.name",
      "customers.id",
      "customers.name"
    ],
    "detail_fields": [
      "orders.id",
      "orders.customer_id",
      "orders.store_id",
      "orders.order_day",
      "orders.order_month",
      "orders.subtotal",
      "orders.tax",
      "orders.total",
      "orders.is_first",
      "items.id",
      "items.order_id",
      "items.sku",
      "products.sku",
      "products.name",
      "products.category",
      "products.price",
      "stores.id",
      "stores.name",
      "customers.id",
      "customers.name"
    ],
    "relationships": [
      "orders_customers",
      "orders_stores",
      "items_orders",
      "items_products"
    ],
    "key_evidence": "trusted",
    "metric_semantics": {
      "order_count": {
        "additivity": "additive"
      },
      "subtotal": {
        "additivity": "additive",
        "unit": "USD"
      },
      "tax": {
        "additivity": "additive",
        "unit": "USD"
      },
      "order_total": {
        "additivity": "additive",
        "unit": "USD"
      },
      "item_count": {
        "additivity": "additive"
      },
      "customer_count": {
        "additivity": "non_additive"
      },
      "first_orders": {
        "additivity": "additive"
      },
      "repeat_orders": {
        "additivity": "additive"
      },
      "average_order_value": {
        "additivity": "non_additive",
        "unit": "USD"
      },
      "revenue": {
        "additivity": "additive",
        "unit": "USD",
        "tags": {
          "owner": "finance",
          "format": "currency"
        }
      }
    },
    "relationship_semantics": {
      "orders_customers": {
        "optional": false,
        "key_evidence": "trusted"
      },
      "orders_stores": {
        "optional": false,
        "key_evidence": "trusted"
      },
      "items_orders": {
        "optional": false,
        "key_evidence": "trusted"
      },
      "items_products": {
        "optional": false,
        "key_evidence": "trusted"
      }
    },
    "dataset_bindings": {
      "orders": {
        "binding_key": "sales",
        "provider_id": "org.queryfarm.fixture.jaffle"
      },
      "items": {
        "binding_key": "sales",
        "provider_id": "org.queryfarm.fixture.jaffle"
      },
      "products": {
        "binding_key": "reference",
        "provider_id": "org.queryfarm.fixture.jaffle"
      },
      "stores": {
        "binding_key": "reference",
        "provider_id": "org.queryfarm.fixture.jaffle"
      },
      "customers": {
        "binding_key": "reference",
        "provider_id": "org.queryfarm.fixture.jaffle"
      }
    },
    "field_semantics": {
      "orders.order_day": {
        "granularity": "day",
        "calendar": "gregorian"
      },
      "orders.order_month": {
        "granularity": "month",
        "calendar": "gregorian"
      },
      "orders.subtotal": {
        "decimal_type": "DECIMAL(18,2)",
        "unit": "USD"
      },
      "orders.tax": {
        "decimal_type": "DECIMAL(18,2)",
        "unit": "USD"
      },
      "orders.total": {
        "decimal_type": "DECIMAL(18,2)",
        "unit": "USD"
      },
      "products.price": {
        "decimal_type": "DECIMAL(18,2)",
        "unit": "USD"
      },
      "stores.name": {
        "comment": "Display name of the store.",
        "tags": {
          "role": "grouping"
        },
        "sql_name": "store_name"
      },
      "orders.is_first": {
        "sql_name": "is_first_order"
      },
      "products.name": {
        "sql_name": "product_name"
      },
      "products.category": {
        "sql_name": "product_category"
      },
      "stores.id": {
        "sql_name": "store_id"
      },
      "customers.id": {
        "sql_name": "customer_id"
      },
      "customers.name": {
        "sql_name": "customer_name"
      }
    },
    "filter_dimensions": [
      "orders.order_day",
      "orders.order_month",
      "orders.is_first",
      "products.name",
      "products.category",
      "stores.id",
      "stores.name",
      "customers.id",
      "customers.name"
    ],
    "tags": {
      "owner": "finance",
      "example": "jaffle-shop"
    }
  }
}

{
  "version": "0.2.0.dev0",
  "name": "jaffle",
  "datasets": [
    {
      "name": "orders",
      "source": "main.orders",
      "primary_key": [
        "id"
      ],
      "fields": [
        {
          "name": "id",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "id"
              }
            ]
          }
        },
        {
          "name": "customer_id",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "customer_id"
              }
            ]
          }
        },
        {
          "name": "store_id",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "store_id"
              }
            ]
          }
        },
        {
          "name": "order_day",
          "datatype": "Date",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "CAST(ordered_at AS DATE)"
              }
            ]
          },
          "dimension": {
            "is_time": true
          }
        },
        {
          "name": "order_month",
          "datatype": "Date",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "CAST(DATE_TRUNC('month', ordered_at) AS DATE)"
              }
            ]
          },
          "dimension": {
            "is_time": true
          }
        },
        {
          "name": "subtotal",
          "datatype": "Decimal",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "subtotal"
              }
            ]
          }
        },
        {
          "name": "tax",
          "datatype": "Decimal",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "tax"
              }
            ]
          }
        },
        {
          "name": "total",
          "datatype": "Decimal",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "total"
              }
            ]
          }
        },
        {
          "name": "is_first",
          "datatype": "Boolean",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "is_first"
              }
            ]
          },
          "dimension": {
            "is_time": false
          }
        }
      ]
    },
    {
      "name": "items",
      "source": "main.items",
      "primary_key": [
        "id"
      ],
      "fields": [
        {
          "name": "id",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "id"
              }
            ]
          }
        },
        {
          "name": "order_id",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "order_id"
              }
            ]
          }
        },
        {
          "name": "sku",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "sku"
              }
            ]
          }
        }
      ]
    },
    {
      "name": "products",
      "source": "main.products",
      "primary_key": [
        "sku"
      ],
      "fields": [
        {
          "name": "sku",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "sku"
              }
            ]
          }
        },
        {
          "name": "name",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "name"
              }
            ]
          },
          "dimension": {
            "is_time": false
          }
        },
        {
          "name": "category",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "category"
              }
            ]
          },
          "dimension": {
            "is_time": false
          }
        },
        {
          "name": "price",
          "datatype": "Decimal",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "price"
              }
            ]
          }
        }
      ]
    },
    {
      "name": "stores",
      "source": "main.stores",
      "primary_key": [
        "id"
      ],
      "fields": [
        {
          "name": "id",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "id"
              }
            ]
          },
          "dimension": {
            "is_time": false
          }
        },
        {
          "name": "name",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "name"
              }
            ]
          },
          "dimension": {
            "is_time": false
          }
        }
      ]
    },
    {
      "name": "customers",
      "source": "main.customers",
      "primary_key": [
        "id"
      ],
      "fields": [
        {
          "name": "id",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "id"
              }
            ]
          },
          "dimension": {
            "is_time": false
          }
        },
        {
          "name": "name",
          "datatype": "String",
          "expression": {
            "dialects": [
              {
                "dialect": "OSSIE_SQL_2026",
                "expression": "name"
              }
            ]
          },
          "dimension": {
            "is_time": false
          }
        }
      ]
    }
  ],
  "relationships": [
    {
      "name": "orders_customers",
      "from": "orders",
      "to": "customers",
      "from_columns": [
        "customer_id"
      ],
      "to_columns": [
        "id"
      ]
    },
    {
      "name": "orders_stores",
      "from": "orders",
      "to": "stores",
      "from_columns": [
        "store_id"
      ],
      "to_columns": [
        "id"
      ]
    },
    {
      "name": "items_orders",
      "from": "items",
      "to": "orders",
      "from_columns": [
        "order_id"
      ],
      "to_columns": [
        "id"
      ]
    },
    {
      "name": "items_products",
      "from": "items",
      "to": "products",
      "from_columns": [
        "sku"
      ],
      "to_columns": [
        "sku"
      ]
    }
  ],
  "metrics": [
    {
      "name": "order_count",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "COUNT(orders.id)"
          }
        ]
      },
      "description": "Order count; independent of the number of order lines."
    },
    {
      "name": "subtotal",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "SUM(orders.subtotal)"
          }
        ]
      },
      "description": "Order amounts excluding tax, in USD."
    },
    {
      "name": "tax",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "SUM(orders.tax)"
          }
        ]
      },
      "description": "Tax collected, in USD."
    },
    {
      "name": "order_total",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "SUM(orders.total)"
          }
        ]
      },
      "description": "Order amounts including tax, in USD."
    },
    {
      "name": "item_count",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "COUNT(items.id)"
          }
        ]
      },
      "description": "Order-line count, including repeated products."
    },
    {
      "name": "customer_count",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "COUNT(DISTINCT orders.customer_id)"
          }
        ]
      }
    },
    {
      "name": "first_orders",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "SUM(CASE WHEN orders.is_first THEN 1 ELSE 0 END)"
          }
        ]
      }
    },
    {
      "name": "repeat_orders",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "SUM(CASE WHEN orders.is_first THEN 0 ELSE 1 END)"
          }
        ]
      }
    },
    {
      "name": "average_order_value",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "order_total / NULLIF(order_count, 0)"
          }
        ]
      }
    },
    {
      "name": "revenue",
      "datatype": "Decimal",
      "description": "Revenue includes collected tax (historical reporting definition).",
      "expression": {
        "dialects": [
          {
            "dialect": "OSSIE_SQL_2026",
            "expression": "order_total"
          }
        ]
      }
    }
  ],
  "description": "Frozen Jaffle Shop reporting population: orders, order lines and store/customer/product dimensions."
}
